<?php
namespace Tests\Feature;
use App\Models\User;
use App\Services\{AiAgents,AiProvider,AiSip,VoiceCapacity};
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\{DB,Http,Crypt,Cache};
use Illuminate\Support\Str;
use Tests\TestCase;
class AiSipTest extends TestCase {
 use RefreshDatabase;
 private string $secret;private string $binding;private string $route;private string $agent;private int $queue;
 protected function setUp():void{parent::setUp();Http::preventStrayRequests();$u=User::factory()->create(['voice_workspace_id'=>1,'voice_role'=>'admin']);$this->actingAs($u);$this->secret='whsec_'.base64_encode(str_repeat('s',32));$this->queue=DB::table('voice_live_queues')->insertGetId(['workspace_id'=>1,'name'=>'Recepção','direction'=>'inbound','inbound_enabled'=>true,'agent_ids'=>'[]']);app(AiProvider::class)->save(1,['api_key'=>'sk-fictional-test-credential','enabled'=>true,'daily_requests'=>100,'sip_secret'=>$this->secret,'project_id'=>'proj_test']);$c=AiAgents::defaults();$c['knowledge']=[['question'=>'Horário','answer'=>'Das 9h às 18h.']];$c['handoff_queue_id']=$this->queue;$a=app(AiAgents::class)->save(1,$u->id,['config'=>$c]);$this->agent=$a['id'];app(AiAgents::class)->publish(1,$u->id,$a['id'],1);config(['ai_test.worker_key'=>str_repeat('k',32)]);Cache::put('ai.voice.worker_seen',time(),45);$b=app(AiSip::class)->configure(1,$u->id,$a['id'],['queue_id'=>$this->queue,'enabled'=>true]);$this->binding=$b['id'];$this->route=$b['route_token'];}
 private function hook(array $changes=[],bool $valid=true,int $offset=0){$event=array_replace_recursive(['id'=>'evt_test','type'=>'realtime.call.incoming','data'=>['call_id'=>'rtc_incoming','sip_headers'=>[['name'=>'X-DiscAI-Route','value'=>$this->route]]]],$changes);$raw=json_encode($event);$time=(string)(time()+$offset);$id='wh_test';$sig=base64_encode(hash_hmac('sha256',$id.'.'.$time.'.'.$raw,str_repeat('s',32),true));return $this->call('POST','/callbacks/ai/sip/'.$this->binding,[],[],[],['CONTENT_TYPE'=>'application/json','HTTP_ACCEPT'=>'application/json','HTTP_WEBHOOK_ID'=>$id,'HTTP_WEBHOOK_TIMESTAMP'=>$time,'HTTP_WEBHOOK_SIGNATURE'=>'v1,'.($valid?$sig:'invalid')],$raw);}
 public function test_signed_sip_accepts_once_and_reserves_shared_capacity():void {Http::fake(['https://api.openai.com/v1/realtime/calls/rtc_incoming/accept'=>Http::response('',200)]);$this->hook()->assertOk()->assertJsonPath('accepted',true);$this->hook()->assertOk()->assertJsonPath('duplicate',true);Http::assertSentCount(1);$this->assertDatabaseCount('ai_sessions',1);$this->assertTrue(app(VoiceCapacity::class)->full());$this->assertDatabaseCount('voice_outbound_calls',0);}
 public function test_bad_signature_timestamp_or_route_token_never_accepts():void {$this->hook([],false)->assertForbidden();$this->hook([],true,-301)->assertForbidden();$this->hook(['data'=>['sip_headers'=>[['name'=>'X-DiscAI-Route','value'=>'wrong']]]])->assertForbidden();Http::assertNothingSent();}
 public function test_disabled_route_or_absent_worker_cannot_accept():void {Http::fake(['https://api.openai.com/v1/realtime/calls/rtc_incoming/reject'=>Http::response('',200)]);DB::table('ai_sip_bindings')->update(['enabled'=>false]);$this->hook()->assertOk()->assertJsonPath('accepted',false);DB::table('ai_sip_bindings')->update(['enabled'=>true]);Cache::forget('ai.voice.worker_seen');$this->hook()->assertOk()->assertJsonPath('accepted',false);Http::assertSentCount(1);}
 public function test_accept_failure_is_not_repeated_and_is_scheduled_for_hangup():void {Http::fake(['https://api.openai.com/v1/realtime/calls/rtc_incoming/accept'=>Http::response([],500)]);$this->hook()->assertStatus(502);$this->hook()->assertOk()->assertJsonPath('duplicate',true);$this->assertDatabaseHas('ai_sessions',['provider_call_id'=>'rtc_incoming','status'=>'closing']);Http::assertSentCount(1);}
 public function test_transfers_require_agent_availability_and_do_not_call_arbitrary_model_targets():void {Http::fake(['https://api.openai.com/v1/realtime/calls/rtc_incoming/accept'=>Http::response('',200)]);$this->hook()->assertOk();$s=DB::table('ai_sessions')->first();$result=app(AiSip::class)->event($s->id,['type'=>'handoff','target_uri'=>'sip:attacker@elsewhere.test']);$this->assertFalse($result['ok']);Http::assertSentCount(1);}
 public function test_worker_end_closes_provider_even_after_api_is_disabled():void {Http::fake(['https://api.openai.com/v1/realtime/calls/rtc_incoming/accept'=>Http::response('',200),'https://api.openai.com/v1/realtime/calls/rtc_incoming/hangup'=>Http::response('',200)]);$this->hook()->assertOk();$s=DB::table('ai_sessions')->first();DB::table('ai_connections')->update(['enabled'=>false]);$result=app(AiSip::class)->event($s->id,['type'=>'ended']);$this->assertTrue($result['ended']);$this->assertDatabaseHas('ai_sessions',['id'=>$s->id,'status'=>'closed']);Http::assertSentCount(2);}
 public function test_internal_poll_requires_signature_and_rejects_replay():void {$this->postJson('/internal/ai/voice/poll')->assertForbidden();$raw='{}';$time=(string)time();$nonce=bin2hex(random_bytes(16));$sig=hash_hmac('sha256',$time.'.'.$nonce.'.internal/ai/voice/poll.'.$raw,str_repeat('k',32));$headers=['CONTENT_TYPE'=>'application/json','HTTP_ACCEPT'=>'application/json','HTTP_X_DISCAI_TIME'=>$time,'HTTP_X_DISCAI_NONCE'=>$nonce,'HTTP_X_DISCAI_SIGNATURE'=>$sig];$this->call('POST','/internal/ai/voice/poll',[],[],[],$headers,$raw)->assertOk()->assertJsonCount(0,'sessions');$this->call('POST','/internal/ai/voice/poll',[],[],[],$headers,$raw)->assertConflict();}
 public function test_credentials_cannot_rotate_during_a_call_but_consumption_can_be_disabled():void {Http::fake(['https://api.openai.com/v1/realtime/calls/rtc_incoming/accept'=>Http::response('',200)]);$this->hook()->assertOk();$this->putJson('/api/ai/connection',['api_key'=>'sk-new-fictional-credential','enabled'=>true,'daily_requests'=>100,'cost_acknowledged'=>true])->assertConflict();$this->putJson('/api/ai/connection',['enabled'=>false,'daily_requests'=>100,'cost_acknowledged'=>true])->assertOk();$this->assertFalse(app(AiProvider::class)->connection(1)['enabled']);$this->assertSame('sk-fictional-test-credential',Crypt::decryptString(DB::table('ai_connections')->value('credentials')));}
}
